import { createClient } from 'contentful'
import {
  CONTENTFUL_SPACE_ID,
  CONTENTFUL_DELIVERY_TOKEN,
  CONTENTFUL_PREVIEW_TOKEN,
} from 'astro:env/server'

const contentfulClient = createClient({
  space: CONTENTFUL_SPACE_ID,
  accessToken: import.meta.env.DEV ? CONTENTFUL_PREVIEW_TOKEN : CONTENTFUL_DELIVERY_TOKEN,
  host: import.meta.env.DEV ? 'preview.contentful.com' : 'cdn.contentful.com',
})

export async function loadTeams() {
  const entries = await contentfulClient.getEntries({ content_type: 'team', include: 2 })
  return entries.items.map((item) => ({
    id: item.sys.id,
    name: item.fields.name as string,
    league: item.fields.league as undefined | string,
    category: mapCategory(item.fields.category),
    sortOrder: parseFloat(
      `${(item.fields.category as any).fields.sortOrder}.${item.fields.sortOrder}`,
    ),
    coach: mapPerson(item.fields.coach),
    contact: mapPerson(item.fields.contact),
    teamID: item.fields.teamID as undefined | string,
  }))
}

function mapCategory(item: any) {
  if (!item) {
    return undefined
  }
  return {
    id: item.sys.id,
    name: item.fields.name as string,
    description: item.fields.description as string,
    sortOrder: item.fields.sortOrder as number,
    isYouthGroup: item.fields.isYouthGroup as boolean,
  }
}

function mapPerson(item: any) {
  if (!item) {
    return undefined
  }
  return {
    id: item.sys.id,
    name: item.fields.name as string,
    position: item.fields.position.fields.name as string,
    email: item.fields.email as undefined | string,
    mobile: mapPhoneNumber(item.fields.mobile),
    phone: mapPhoneNumber(item.fields.phone),
  }
}

function mapPhoneNumber(item: any) {
  if (!item) {
    return undefined
  }
  return {
    id: item.sys.id,
    formatted: item.fields.formatted as string,
    raw: item.fields.raw as string,
  }
}

export async function loadSponsors() {
  const entries = await contentfulClient.getEntries({ content_type: 'sponsor' })
  return entries.items.map((item) => ({
    id: item.sys.id,
    name: item.fields.name as string,
    groupBy: (item.fields.groupBy as string) || (item.fields.name as string),
  }))
}

import { describe, expect, it } from 'vitest'
import {
  AvailabilityState,
  availabilityState,
  calculateAvailabilityMessage,
  canSubscribe,
  convertToEventAvailability,
} from '@/api/events'
import type { RawEventCounter } from '@/types'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

const counter = (fields: Partial<RawEventCounter>): RawEventCounter => ({
  id: 'evt-1',
  max_subscribers: 10,
  subscribers: 0,
  waiting_list: 0,
  max_waiting_list: 5,
  ...fields,
})

describe('convertToEventAvailability — producer sentinel + phase switch', () => {
  const cases: Array<{
    name: string
    input: RawEventCounter
    expectedSlots: number
    expectedWaitingList: boolean
    expectedState: AvailabilityState
    expectedMessage: string
  }> = [
    {
      name: 'Unlimited event (max_subscribers === -1): sentinel -1, subscriber phase',
      input: counter({ max_subscribers: -1, subscribers: 999 }),
      expectedSlots: -1,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Unlimited,
      expectedMessage: 'Freie Plätze verfügbar',
    },
    {
      name: 'Subscribers open, many slots remaining',
      input: counter({ max_subscribers: 10, subscribers: 2 }),
      expectedSlots: 8,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Subscribing,
      expectedMessage: 'Noch 8 freie Plätze',
    },
    {
      name: 'Subscribers open, exactly one slot remaining (singular message)',
      input: counter({ max_subscribers: 10, subscribers: 9 }),
      expectedSlots: 1,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Subscribing,
      expectedMessage: 'Noch 1 freier Platz',
    },
    {
      name: 'Subscribers full, waiting-list open: phase switches, isWaitingList true',
      input: counter({
        max_subscribers: 10,
        subscribers: 10,
        max_waiting_list: 5,
        waiting_list: 1,
      }),
      expectedSlots: 4,
      expectedWaitingList: true,
      expectedState: AvailabilityState.WaitingList,
      expectedMessage: 'Warteliste ist geöffnet',
    },
    {
      name: 'Subscribers and waiting-list full: 0 + isWaitingList true (FullyBooked)',
      input: counter({
        max_subscribers: 10,
        subscribers: 10,
        max_waiting_list: 5,
        waiting_list: 5,
      }),
      expectedSlots: 0,
      expectedWaitingList: true,
      expectedState: AvailabilityState.FullyBooked,
      expectedMessage: 'Ausgebucht',
    },
    {
      name: 'Unlimited event ignores the waiting-list phase entirely',
      input: counter({
        max_subscribers: -1,
        subscribers: 999,
        max_waiting_list: 0,
        waiting_list: 0,
      }),
      expectedSlots: -1,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Unlimited,
      expectedMessage: 'Freie Plätze verfügbar',
    },
    {
      name: 'Subscribers exactly at capacity but waiting-list open does NOT underflow below zero',
      input: counter({
        max_subscribers: 10,
        subscribers: 12,
        max_waiting_list: 3,
        waiting_list: 0,
      }),
      expectedSlots: 3,
      expectedWaitingList: true,
      expectedState: AvailabilityState.WaitingList,
      expectedMessage: 'Warteliste ist geöffnet',
    },
    {
      name: 'Negative phantom: subscribers exceed cap and waiting-list exceeds cap clamps to 0',
      input: counter({
        max_subscribers: 10,
        subscribers: 15,
        max_waiting_list: 4,
        waiting_list: 9,
      }),
      expectedSlots: 0,
      expectedWaitingList: true,
      expectedState: AvailabilityState.FullyBooked,
      expectedMessage: 'Ausgebucht',
    },
  ]

  for (const c of cases) {
    it(c.name, () => {
      const av = convertToEventAvailability(c.input)
      expect(av.availableSlots).toBe(c.expectedSlots)
      expect(av.isWaitingList).toBe(c.expectedWaitingList)
      expect(av.message).toBe(c.expectedMessage)
      expect(availabilityState(av)).toBe(c.expectedState)
    })
  }
})

describe('availabilityState — sentinel + phase decode (the one canonical read site)', () => {
  const cases: Array<{
    name: string
    slots: number
    waiting: boolean
    expected: AvailabilityState
  }> = [
    {
      name: 'sentinel -1 ⇒ Unlimited regardless of isWaitingList (well-formed input)',
      slots: -1,
      waiting: false,
      expected: AvailabilityState.Unlimited,
    },
    {
      name: 'subscriber phase, slots remaining ⇒ Subscribing',
      slots: 5,
      waiting: false,
      expected: AvailabilityState.Subscribing,
    },
    {
      name: 'subscriber phase, exactly one slot ⇒ Subscribing',
      slots: 1,
      waiting: false,
      expected: AvailabilityState.Subscribing,
    },
    {
      name: 'waiting-list phase, slots remaining ⇒ WaitingList',
      slots: 3,
      waiting: true,
      expected: AvailabilityState.WaitingList,
    },
    {
      name: 'waiting-list phase, exactly one slot ⇒ WaitingList',
      slots: 1,
      waiting: true,
      expected: AvailabilityState.WaitingList,
    },
    {
      name: 'waiting-list phase, zero slots ⇒ FullyBooked',
      slots: 0,
      waiting: true,
      expected: AvailabilityState.FullyBooked,
    },
    {
      name: 'subscriber phase, zero slots ⇒ FullyBooked (unreachable in producer but defensive)',
      slots: 0,
      waiting: false,
      expected: AvailabilityState.FullyBooked,
    },
  ]

  for (const c of cases) {
    it(c.name, () => {
      expect(availabilityState({ availableSlots: c.slots, isWaitingList: c.waiting })).toBe(
        c.expected,
      )
    })
  }
})

describe('calculateAvailabilityMessage — message derives through the state predicate', () => {
  const cases: Array<{ slots: number; waiting: boolean; expected: string }> = [
    { slots: -1, waiting: false, expected: 'Freie Plätze verfügbar' },
    { slots: 5, waiting: false, expected: 'Noch 5 freie Plätze' },
    { slots: 1, waiting: false, expected: 'Noch 1 freier Platz' },
    { slots: 3, waiting: true, expected: 'Warteliste ist geöffnet' },
    { slots: 1, waiting: true, expected: 'Warteliste ist geöffnet' },
    { slots: 0, waiting: true, expected: 'Ausgebucht' },
    { slots: 0, waiting: false, expected: 'Ausgebucht' },
  ]

  for (const { slots, waiting, expected } of cases) {
    it(`slots=${slots}, isWaitingList=${waiting} ⇒ "${expected}"`, () => {
      expect(calculateAvailabilityMessage({ availableSlots: slots, isWaitingList: waiting })).toBe(
        expected,
      )
    })
  }
})

describe('canSubscribe — "is booking open" predicate', () => {
  const cases: Array<{ name: string; slots: number; waiting: boolean; expected: boolean }> = [
    { name: 'Unlimited ⇒ true', slots: -1, waiting: false, expected: true },
    { name: 'Subscribing with many slots ⇒ true', slots: 5, waiting: false, expected: true },
    { name: 'Subscribing with one slot ⇒ true', slots: 1, waiting: false, expected: true },
    { name: 'WaitingList open ⇒ false', slots: 3, waiting: true, expected: false },
    { name: 'WaitingList with one slot ⇒ false', slots: 1, waiting: true, expected: false },
    { name: 'FullyBooked (waiting full) ⇒ false', slots: 0, waiting: true, expected: false },
    {
      name: 'FullyBooked (defensive, subscriber zero) ⇒ false',
      slots: 0,
      waiting: false,
      expected: false,
    },
  ]

  for (const { name, slots, waiting, expected } of cases) {
    it(name, () => {
      expect(canSubscribe({ availableSlots: slots, isWaitingList: waiting })).toBe(expected)
    })
  }
})

describe('-1 contract — the sentinel is pinned to exactly two sites', () => {
  const moduleSource = readFileSync(resolve(process.cwd(), 'src/api/events.ts'), 'utf8')

  it('Unlimited never produces a "Noch N" or "Ausgebucht" message', () => {
    expect(calculateAvailabilityMessage({ availableSlots: -1, isWaitingList: false })).toBe(
      'Freie Plätze verfügbar',
    )
    expect(calculateAvailabilityMessage({ availableSlots: -1, isWaitingList: true })).toBe(
      'Freie Plätze verfügbar',
    )
  })

  it('availabilityState reads === -1 (the canonical decode site)', () => {
    expect(availabilityState.toString()).toContain('=== -1')
  })

  it('calculateAvailabilityMessage never compares === -1 — it delegates to availabilityState', () => {
    const fnSource = extractFunctionSource(moduleSource, 'calculateAvailabilityMessage')
    expect(fnSource).not.toContain('=== -1')
  })

  it('canSubscribe never compares === -1 — it delegates to availabilityState', () => {
    const fnSource = extractFunctionSource(moduleSource, 'canSubscribe')
    expect(fnSource).not.toContain('=== -1')
  })
})

function extractFunctionSource(source: string, name: string): string {
  const start = source.indexOf(`function ${name}`)
  if (start === -1) throw new Error(`function ${name} not found in source`)
  let depth = 0
  let bodyStart = -1
  for (let i = start; i < source.length; i++) {
    if (source[i] === '{') {
      if (bodyStart === -1) bodyStart = i
      depth++
    } else if (source[i] === '}') {
      depth--
      if (depth === 0) return source.slice(start, i + 1)
    }
  }
  throw new Error(`unterminated function ${name}`)
}

import {
  EventType,
  type Booking,
  type BookingResponse,
  type Event,
  type EventAvailability,
  type RawEvent,
  type RawEventCounter,
} from '@/types'
import { formatCurrency, formatDuration } from '@/utils'
import { BACKEND_API, PREVIEW } from 'astro:env/client'
import { parseISO, format, getDay } from 'date-fns'
import { de } from 'date-fns/locale'

/**
 * Four-state phase machine derived from {@link EventAvailability}. Tests pin
 * every transition; consumer sites must branch on this enum rather than
 * re-decoding the `-1` / `0` sentinels themselves, so a future sentinel change
 * (e.g. to `Infinity` or a `kind: 'unlimited'` discriminated field) either
 * moves every site together or fails a test.
 *
 * Lives in `src/api/events.ts` (not `src/types.ts`) so the browser `<script>`
 * bundles that import it as a runtime value do not pull `@/types` — and with
 * it the side-effectful `zod` import — into the client bundle.
 */
export enum AvailabilityState {
  /** Subscriber phase, no capacity limit (`max_subscribers === -1`). Sentinel `-1`. */
  Unlimited = 'unlimited',
  /** Subscriber phase, slots remaining. */
  Subscribing = 'subscribing',
  /** Subscribers full; waiting-list phase open. */
  WaitingList = 'waitingList',
  /** Subscribers full and waiting-list full. Terminal. */
  FullyBooked = 'fullyBooked',
}

/**
 * Canonical decode of the {@link EventAvailability} sentinel + phase switch
 * into a single {@link AvailabilityState}. This is the ONLY function that
 * should read `availableSlots === -1` or `availableSlots === 0`; everywhere
 * else derives through this predicate or {@link canSubscribe}.
 */
export function availabilityState(
  av: Pick<EventAvailability, 'availableSlots' | 'isWaitingList'>,
): AvailabilityState {
  if (av.availableSlots === -1) {
    return AvailabilityState.Unlimited
  }
  if (av.isWaitingList) {
    return av.availableSlots > 0 ? AvailabilityState.WaitingList : AvailabilityState.FullyBooked
  }
  return av.availableSlots > 0 ? AvailabilityState.Subscribing : AvailabilityState.FullyBooked
}

/**
 * Whether the booking form is open for this event — `true` for the
 * `Unlimited` and `Subscribing` phases, `false` once the waiting-list or
 * fully-booked phases begin. Captures the "is booking open" question the
 * `Event.astro` consumer used to re-derive inline from two enum values; goes
 * through {@link availabilityState} so it never reads the sentinel directly.
 */
export function canSubscribe(
  av: Pick<EventAvailability, 'availableSlots' | 'isWaitingList'>,
): boolean {
  const state = availabilityState(av)
  return state === AvailabilityState.Unlimited || state === AvailabilityState.Subscribing
}

export async function loadEvents(type: EventType): Promise<Event[]> {
  const response = await fetch(`${BACKEND_API}/events?type=${type}&beta=${PREVIEW}`)
  if (!response.ok) {
    throw new Error(`Failed to load events: ${response.status} ${response.statusText}`)
  }
  const events: RawEvent[] = await response.json()
  return await Promise.all(
    events
      .sort((a, b) => a.sort_index - b.sort_index)
      .filter((event) => event.type === type)
      .map<Promise<Event>>(async (event) => {
        return {
          id: event.id,
          name: event.name,
          image: `/src/assets/events/${event.image}`,
          sortIndex: event.sort_index,
          shortDescription: event.short_description,
          description: event.description,
          location: event.location,
          dates: event.custom_date ? [event.custom_date] : event.dates,
          datesDisplay: computeDatesDisplay(event.dates, event.custom_date),
          duration: durationPrefix(event.type) + formatDuration(event.duration_in_minutes),
          priceMember: formatCurrency(event.price_member),
          priceNonMember: formatCurrency(event.price_non_member),
          externalOperator: event.external_operator,
          altBookingButtonText: event.alt_booking_button_text || undefined,
          customFields: event.custom_fields.map((field) => ({
            name: field.name,
            type: field.type,
            minValue: field.min_value || undefined,
            maxValue: field.max_value || undefined,
          })),
          paymentMethod: event.payment_method,
        }
      }),
  )
}

function durationPrefix(type: EventType) {
  switch (type) {
    case EventType.Fitness:
      return 'Kurslänge: '
    case EventType.Events:
      return 'Eventlänge: ca. '
  }
}

function computeDatesDisplay(dates: string[], customDate?: string | null): string | undefined {
  if (customDate) {
    return customDate
  }
  if (dates.length === 0) {
    return undefined
  }

  try {
    if (dates.length === 1) {
      return format(parseISO(dates[0]), 'eee, d. MMM, H:mm', { locale: de }) + ' Uhr'
    }

    const first = parseISO(dates[0])
    const firstDay = getDay(first)
    const firstTime = format(first, 'H:mm')

    const allSamePattern = dates.every((dateStr) => {
      const d = parseISO(dateStr)
      return getDay(d) === firstDay && format(d, 'H:mm') === firstTime
    })

    if (allSamePattern) {
      const weekday = format(first, 'eee', { locale: de })
      return `${weekday}, ${firstTime} Uhr (${dates.length} Termine)`
    }

    return `${format(first, 'd. MMM, H:mm', { locale: de })} Uhr (+${dates.length - 1} weitere)`
  } catch {
    return dates.length === 1 ? dates[0] : `${dates[0]} (+${dates.length - 1} weitere)`
  }
}

export function convertToEventAvailability(counter: RawEventCounter): EventAvailability {
  const noLimit = counter.max_subscribers === -1
  const noMoreSubscriptions = counter.subscribers >= counter.max_subscribers
  const noMoreWaitingList = counter.waiting_list >= counter.max_waiting_list

  const availableSlots = noLimit
    ? -1
    : noMoreSubscriptions
      ? noMoreWaitingList
        ? 0
        : Math.max(0, counter.max_waiting_list - counter.waiting_list)
      : Math.max(0, counter.max_subscribers - counter.subscribers)

  const isWaitingList = !noLimit && noMoreSubscriptions

  return {
    availableSlots,
    isWaitingList,
    message: calculateAvailabilityMessage({ availableSlots, isWaitingList }),
  }
}

export function calculateAvailabilityMessage(
  av: Pick<EventAvailability, 'availableSlots' | 'isWaitingList'>,
): string {
  switch (availabilityState(av)) {
    case AvailabilityState.Unlimited:
      return 'Freie Plätze verfügbar'
    case AvailabilityState.WaitingList:
      return 'Warteliste ist geöffnet'
    case AvailabilityState.Subscribing:
      return av.availableSlots === 1
        ? 'Noch 1 freier Platz'
        : `Noch ${av.availableSlots} freie Plätze`
    case AvailabilityState.FullyBooked:
      return 'Ausgebucht'
  }
}

export async function loadEventAvailability(
  id: string,
  callback: (availability: EventAvailability) => void,
) {
  loadEventsAvailability((record) => {
    const availability = record[id]
    if (availability) {
      callback(availability)
    }
  })
}

interface Cache {
  timestamp: number
  data: Record<string, EventAvailability>
}
const sessionStorageKey = 'eventAvailability'

export async function loadEventsAvailability(
  callback: (availability: Record<string, EventAvailability>) => void,
) {
  // Try to load availability from session storage
  const storage = sessionStorage.getItem(sessionStorageKey)
  if (storage) {
    try {
      const cache: Cache = JSON.parse(storage)
      // Only use cached availability if it is not older than 1 hour
      if (cache.timestamp > Date.now() - 3600000) {
        callback(cache.data)
      }
    } catch (e) {
      console.error('Error while parsing event availability from session storage', e)
    }
  }

  // Fetch availability from backend
  const response = await fetch(`${BACKEND_API}/events/counter?beta=${PREVIEW}`)
  if (!response.ok) {
    throw new Error(`Failed to load event availability: ${response.status} ${response.statusText}`)
  }
  const counters: RawEventCounter[] = await response.json()
  processCounters(counters, callback)
}

function processCounters(
  counters: RawEventCounter[],
  callback: (availability: Record<string, EventAvailability>) => void,
) {
  const availability: Record<string, EventAvailability> = {}
  for (const counter of counters) {
    availability[counter.id] = convertToEventAvailability(counter)
  }
  callback(availability)

  // Store availability in session storage
  const cache: Cache = { timestamp: Date.now(), data: availability }
  sessionStorage.setItem(sessionStorageKey, JSON.stringify(cache))
}

export async function bookEvent(
  formData: Booking,
  token: string,
  callback: (availability: EventAvailability) => void,
) {
  const response = await fetch(`${BACKEND_API}/events/booking`, {
    method: 'POST',
    body: JSON.stringify({ ...formData, token }),
    headers: {
      'Content-Type': 'application/json',
    },
  })
  if (response.ok) {
    const data: BookingResponse = await response.json()
    if (data.counter.length > 0) {
      processCounters(data.counter, (record) => {
        const availability = record[formData.event_id]
        if (availability) {
          callback(availability)
        }
      })
    }
    return { success: data.success, message: data.message }
  }
  return {
    success: false,
    message: 'Es ist ein Fehler aufgetreten. Bitte versuche es später noch einmal.',
  }
}

export async function prebooking(hash: string) {
  const response = await fetch(`${BACKEND_API}/events/prebooking/${hash}`)
  if (response.ok) {
    const data: BookingResponse = await response.json()
    return {
      success: data.success,
      message: data.message,
      requires_iban: data.requires_iban || false,
    }
  }
  return {
    success: false,
    message: 'Es ist ein Fehler aufgetreten. Bitte versuche es später noch einmal.',
  }
}

export async function prebookWithIban(hash: string, iban: string) {
  const response = await fetch(`${BACKEND_API}/events/prebooking/${hash}/iban`, {
    method: 'POST',
    body: JSON.stringify({ iban }),
    headers: {
      'Content-Type': 'application/json',
    },
  })
  if (response.ok) {
    const data: BookingResponse = await response.json()
    return { success: data.success, message: data.message }
  }
  return {
    success: false,
    message: 'Es ist ein Fehler aufgetreten. Bitte versuche es später noch einmal.',
  }
}

