  vi.resetModules()
  return await import('@/api/contentful')
}

// Reference `AnyEntry` so the type import isn't elided (eslint/TS strict unused).
void (null as unknown as AnyEntry)

// ─── Test lifecycle ────────────────────────────────────────────────────

beforeEach(() => {
  vi.clearAllMocks()
})

afterEach(() => {
  vi.unstubAllEnvs()
  vi.resetModules()
})

