    const teams = await loadTeams()
    expect(teams[0].coach).toEqual({
      id: 'person-1',
      name: 'Max Mustermann',
      position: 'Trainer',
      email: 'max@example.org',
      mobile: { formatted: '+49 176 12345678', raw: '+4917612345678' },
      phone: { formatted: '+49 7459 1204', raw: '+4974591204' },
    })
  })

  it('reads `position` from the linked position entry name', async () => {
    installClient([rawTeamEntry])
